// This code goes inside the "Split cover letter from resume" node.
// It cleans and correctly parses the LLM output.

// Get the full output from the LLM node
const llmOutput = $('🔥Write Cover Letter & Rewrite Resume1').item.json.text;

// Clean up the output by removing the markdown code blocks and extra whitespace
const cleanedOutput = llmOutput.replace(/```(html)?\n|```/g, '').trim();

// Split the output into two parts based on the headings
const parts = cleanedOutput.split('### COVER LETTER ###');

// Extract the resume and remove the resume heading
const resumeHtml = parts[0].replace('### REWRITTEN RESUME ###', '').trim();

// Extract the cover letter and remove any extra whitespace
const coverLetterHtml = parts[1].trim();

// Return the job data with the new, correctly separated properties
return [{
  json: {
    job_title: $('Loop Over Items').item.json.job_title || "Title Not Found",
    company_name: $('Loop Over Items').item.json.company_name || "Company Not Found",
    job_url: $('Loop Over Items').item.json.job_url || "#",
    job_description: $('Loop Over Items').item.json.job_description,
    email: $('Webhook').item.json.body.email,
    cover_letter: coverLetterHtml,
    tailored_resume: resumeHtml
  }
}];

// Debug version - collect all jobs after loop completes
console.log("=== COLLECTING ALL JOBS ===");

try {
  // Get all processed jobs from "Prepare Final Job" node
  const jobResults = $items("Prepare Final Job");
  console.log("Total items from Prepare Final Job:", jobResults.length);

  const allJobs = [];
  jobResults.forEach((item, index) => {
    if (item && item.json) {
      console.log(`Job ${index + 1}:`, item.json.job_title);
      allJobs.push({
        job_title: item.json.job_title || "Title Not Found",
        company_name: item.json.company_name || "Company Not Found",
        job_url: item.json.job_url || "#",
        job_description: item.json.job_description || "No description",
        cover_letter: item.json.cover_letter || "Cover letter not available",
        tailored_resume: item.json.tailored_resume || "Resume not available",
        email: item.json.email || ""
      });
    }
  });

  console.log("FINAL RESULT: Collected", allJobs.length, "jobs");

  return [{
    json: {
      jobs: allJobs,
      totalProcessed: allJobs.length
    }
  }];

} catch (error) {
  console.log("Collection error:", error.message);
  return [{
    json: {
      jobs: [],
      totalProcessed: 0,
      error: error.message
    }
  }];
}

// Set the maximum number of jobs you want to process.
const maxJobs = 10;

// This line takes the full list of jobs and returns only the first 15.
return items.slice(0, maxJobs);

const seen = new Set();

function normalizeText(text) {
  return text.toLowerCase()
    .trim()
    .replace(/[^\w\s]/g, '') // Remove special characters
    .replace(/\s+/g, ' ');   // Normalize whitespace
}

return items.filter(item => {
  const job = item.json;

  // Extract with fallbacks and normalize
  const title = normalizeText(
    job.title || job.jobTitle || job.job_title || job.name || 
    job.position || job.positionTitle || job.role || job.jobName ||
    job.job?.title || ''
  );

  const company = normalizeText(
    job.company || job.companyName || job.company_name || 
    job.employer || job.organization || job.job?.company || ''
  );

  const description = normalizeText(
    (job.description || job.jobDescription || job.job_description || 
     job.summary || job.details || job.job?.description || '')
    .substring(0, 100)
  );

  // Skip if we don't have enough data to create a meaningful key
  if (!title && !company) {
    return true; // Keep items we can't properly identify
  }

  const key = `${title}-${company}-${description}`;

  if (seen.has(key)) {
    return false;
  }
  seen.add(key);
  return true;
});

// Safer approach to access data
const inputData = $input.all();
console.log("Input data received:", inputData.length, "items");

if (inputData.length === 0) {
  return [{
    json: {
      status: 'failure',
      reason: 'No data received from collection node'
    }
  }];
}

const collectedData = inputData[0].json;
console.log("Collected data structure:", Object.keys(collectedData));

const successfulJobs = collectedData.jobs || [];
console.log("Jobs found:", successfulJobs.length);

// Get webhook data using items() instead of accessing directly
const webhookItems = $items("Webhook");
const webhookData = webhookItems[0].json;
const userEmail = webhookData.body.email;
const userName = webhookData.body.name;
const transactionId = webhookData.body.transactionId;
const submissionId = webhookData.body.submissionId;

// Rest of your email building logic stays the same...
if (successfulJobs.length === 0) {
  return [{
    json: {
      status: 'failure',
      reason: 'No matching jobs were found to process after filtering.',
      userEmail,
      userName,
      transactionId,
      submissionId
    }
  }];
}

// Build email HTML (keeping your existing code)
let emailHtml = `
<html>
  <body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
    <p>Hi ${userName},</p>
    <p>Your JobMonkey request is complete! Here are the tailored resume(s) and cover letter(s) for the ${successfulJobs.length} job(s) that was/were successfully processed:</p>
`;

let jobCounter = 1;
for (const jobData of successfulJobs) {
  const jobTitle = jobData.job_title || 'Title Not Available';
  const companyName = jobData.company_name || jobData.company || 'Company Not Available';
  const jobUrl = jobData.job_url || '#';
  const coverLetter = jobData.cover_letter || 'Cover letter not available';
  const tailoredResume = jobData.tailored_resume || 'Resume not available';

  emailHtml += `
    <hr style="margin: 30px 0; border: 1px solid #ccc;">
    <h2>Job #${jobCounter}: ${jobTitle} at ${companyName}</h2>
    <p><strong>Job URL:</strong> <a href="${jobUrl}">${jobUrl}</a></p>

    <h3>Your Cover Letter:</h3>
    <div style="background: #f9f9f9; padding: 15px; border: 1px solid #eee; border-radius: 8px; margin-bottom: 15px;">
      ${coverLetter}
    </div>

    <h3>Your Tailored Resume:</h3>
    <div style="background: #f9f9f9; padding: 15px; border: 1px solid #eee; border-radius: 8px;">
      ${tailoredResume}
    </div>
  `;
  jobCounter++;
}

emailHtml += `
    <hr style="margin-top: 30px;">
    <p>Good luck with your applications!</p>
    <p>The JobMonkey Team</p>
  </body>
</html>
`;

return [{
  json: {
    finalEmailBody: emailHtml,
    userEmail,
    userName,
    status: 'success',
    submissionId
  }
}];
